#include <stdio.h>

/* 标志法操作序列模拟：
 * ops 形如 "0:set" "1:enter" ...（进程号:动作）
 * 返回临界区内同时存在的最大进程数。
 */
int solve(const char **ops, int n) {
    int flag[2] = {0, 0};
    int in_cs = 0, max_cs = 0;
    for (int k = 0; k < n; k++) {
        int i = ops[k][0] - '0';   /* 进程号 */
        const char *act = ops[k] + 2;  /* 跳过 "i:" */
        if (act[0] == 's') {                 /* set */
            flag[i] = 1;
        } else if (act[0] == 'c') {          /* clear */
            flag[i] = 0;
        } else if (act[0] == 'e' && act[1] == 'n') {  /* enter */
            if (++in_cs > max_cs) max_cs = in_cs;
        } else if (act[0] == 'e' && act[1] == 'x') {  /* exit */
            in_cs--;
        }
    }
    (void)flag;
    return max_cs;
}

