def solve(ops):
    flag = [False, False]
    in_cs = 0
    max_cs = 0
    for op in ops:
        idx_str, action = op.split(":")
        i = int(idx_str)
        if action == "set":
            flag[i] = True
        elif action == "clear":
            flag[i] = False
        elif action == "enter":
            in_cs += 1
            if in_cs > max_cs:
                max_cs = in_cs
        elif action == "exit":
            in_cs -= 1
    return max_cs
